#include <iostream>
#include <vector>

void displayVector(const std::vector<int>& vec) {
    for (std::size_t i = 0; i < vec.size(); ++i) {
        std::cout << vec[i] << (i + 1 == vec.size() ? "" : " ");
    }
    std::cout << "\n";
}

int main() {
    // Create a vector of 5 integers initialized to 0
    std::vector<int> numbers(5);

    std::cout << "Size: " << numbers.size() << "\n";
    std::cout << "Initial contents: ";
    displayVector(numbers);

    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

int main() {
    std::vector<int> v1 = {10, 20, 30};
    std::vector<int> v2 = {10, 20, 30};

    // Equality check
    if (v1 == v2) {
        std::cout << "v1 and v2 are equal\n";
    }

    // Using [] as lvalue
    v1[1] = 99;
    std::cout << "v1[1] is now " << v1[1] << "\n";

    if (v1 != v2) {
        std::cout << "v1 and v2 are not equal after modification\n";
    }

    // Safe bounds checking using .at() and try/catch
    try {
        std::cout << "Attempting to access index 10:\n";
        std::cout << v1.at(10) << "\n";
    } catch (const std::out_of_range& ex) {
        std::cout << "Caught exception: out of range index\n";
    }

    return 0;
}
